package app.dayflow;
import android.view.View;
import android.widget.*;
import org.json.*;
import java.time.*;
import java.util.*;

/** Secondary progressive disclosure; the home screen still contains only today's items. */
final class FuturePlans {
    static void show(MainActivity a){LinearLayout page=a.fullPage("近期与远期",()->PlanHub.show(a));page.addView(Ui.text(a,"近期与远期",24,true));page.addView(Ui.help(a,"未来7天展开，更远按周或月折叠；没有确定日期的事项单独保留。"));try{LocalDate today=LocalDate.now();JSONArray rows=Data.get(a).scheduled(today,today.plusDays(366),false);Map<String,List<JSONObject>> groups=new LinkedHashMap<>();for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);if(!r.optString("completed").isEmpty())continue;LocalDate date=PlanTime.start(r).toLocalDate();long days=java.time.temporal.ChronoUnit.DAYS.between(today,date);String group=days<7?"未来7天":days<35?"周 · "+date.with(java.time.temporal.TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY)):"月 · "+YearMonth.from(date);JSONObject brief=new JSONObject();for(String key:new String[]{"id","title","start_at","end_at","due_date","all_day","series_id","occurrence_date"})if(r.has(key))brief.put(key,r.get(key));groups.computeIfAbsent(group,k->new ArrayList<>()).add(brief);}for(Map.Entry<String,List<JSONObject>> group:groups.entrySet()){LinearLayout items=Ui.column(a);boolean open=group.getKey().equals("未来7天");items.setVisibility(open?View.VISIBLE:View.GONE);boolean[] loaded={false};Runnable load=()->{if(loaded[0])return;loaded[0]=true;int count=0;for(JSONObject r:group.getValue()){if(count++>=30)break;items.addView(Ui.button(a,r.optString("title")+" · "+PlanTime.label(r),false,()->{try{JSONObject full=Data.get(a).resolve(r.optString("id"),r.optString("series_id"),r.optString("occurrence_date"));if(full!=null)a.detail(full);else a.message("事项已变化，请刷新列表");}catch(Exception e){a.message(e.getMessage());}}));}if(group.getValue().size()>30)items.addView(Ui.button(a,"按日期查看本组其余事项",false,()->PlanHub.calendar(a,PlanTime.start(group.getValue().get(0)).toLocalDate(),"week")));};page.addView(Ui.button(a,group.getKey()+" · "+group.getValue().size()+"项",false,()->{boolean expand=items.getVisibility()!=View.VISIBLE;if(expand)load.run();items.setVisibility(expand?View.VISIBLE:View.GONE);}));page.addView(items);if(open)load.run();}if(groups.isEmpty())page.addView(Ui.help(a,"近期没有待完成安排"));page.addView(Ui.button(a,"时间待定事项",false,a::tasks));page.addView(Ui.button(a,"查看一年以后的日期",false,()->MonthBrowser.show(a,today.plusYears(1),d->DailyTasks.show(a,d))));}catch(Exception e){a.message(e.getMessage());}}
}
